// =====================================================================
// CONFIGURATION — reprise des Zaps Zapier « Typeform → Send Email »
// La ligne 77 reproduit le Zap d'origine (capture d'écran).
// TODO : vérifier/adapter to, cc, subject et greeting pour les 8 autres
// campus en recopiant les valeurs de chaque Zap avant de le couper.
// =====================================================================
const FROM_NAME = 'thibaud@athena-bs.fr';

const CAMPUS = {
  // form_id Typeform : { destinataires }
  GoYjt7QL: { campus: '06', subject: 'Dépôt de facture - Nice',        greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  wWiTmFbt: { campus: '13', subject: 'Dépôt de facture - Marseille',   greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  Ei4mhN30: { campus: '34', subject: 'Dépôt de facture - Montpellier', greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  prq60cLp: { campus: '66', subject: 'Dépôt de facture - Perpignan',   greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  ISq3V0un: { campus: '69', subject: 'Dépôt de facture - Lyon',        greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  O6cupDZd: { campus: '77', subject: 'Dépôt de facture - CSM',         greeting: 'Samia', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' },
  M6EyJ8VW: { campus: '91', subject: 'Dépôt de facture - Evry',        greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  zKkRmCZi: { campus: '93', subject: 'Dépôt de facture - Villepinte',  greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
  STqpGfRz: { campus: '94', subject: 'Dépôt de facture - Villejuif',   greeting: '', to: 'samia@athena-bs.fr', cc: 'elodie@athena-bs.fr, lisa@athena-bs.fr' }, // TODO vérifier
};

// =====================================================================

const out = [];

for (const item of $input.all()) {
  const fr = item.json; // form_response complet du webhook Typeform
  const conf = CAMPUS[fr.form_id];
  if (!conf) {
    throw new Error(`Formulaire inconnu : ${fr.form_id} — ajoutez-le dans CAMPUS.`);
  }

  // Les réponses référencent les champs par id ; les intitulés (identiques
  // sur les 9 formulaires) sont dans definition.fields du payload.
  const titleById = {};
  for (const f of (fr.definition && fr.definition.fields) || []) {
    titleById[f.id] = (f.title || '').trim();
  }

  const answers = {};
  for (const a of fr.answers || []) {
    const title = titleById[(a.field && a.field.id) || ''] || '';
    let val = '';
    switch (a.type) {
      case 'choice':   val = a.choice && (a.choice.label || a.choice.other); break;
      case 'choices':  val = a.choices && (a.choices.labels || []).join(', '); break;
      case 'text':     val = a.text; break;
      case 'date':     val = a.date; break;
      case 'number':   val = String(a.number); break;
      case 'boolean':  val = a.boolean ? 'Oui' : 'Non'; break;
      case 'email':    val = a.email; break;
      case 'file_url': val = a.file_url; break;
      default:         val = a[a.type] != null ? String(a[a.type]) : '';
    }
    if (title) answers[title] = val || '';
  }

  const exact = (t) => answers[t] || '';
  const byPrefix = (p) => {
    for (const [t, v] of Object.entries(answers)) {
      if (t.toLowerCase().startsWith(p.toLowerCase())) return v;
    }
    return '';
  };

  const quiDepose         = exact('Qui dépose');
  const compteDebiteur    = exact('Compte débiteur');
  const typeFacture       = exact('Type de facture');
  const typeFactureMarket = exact('Type de facture (Market)');
  const commercant        = exact('Commerçant');
  const dateFacture       = exact('Date de la facture');
  const montant           = byPrefix('Montant');
  const fileUrl           = exact('Facture') || byPrefix('Facture');

  // Une seule des deux questions « Type de facture » est posée (logique du
  // formulaire) — Zapier concaténait les deux, l'une étant vide.
  const type = [typeFacture, typeFactureMarket].filter(Boolean).join('');

  const hello = conf.greeting ? `Hello ${conf.greeting},` : 'Bonjour,';
  const body = [
    hello,
    '',
    `${quiDepose} vient de déposer une nouvelle facture "${type}" datant du ${dateFacture} d'un montant de ${montant} € chez ${commercant} à débiter du ${compteDebiteur}. Merci !`,
  ].join('\n');

  let fileName = 'facture.pdf';
  try {
    fileName = decodeURIComponent(new URL(fileUrl).pathname.split('/').pop()) || fileName;
  } catch (e) { /* URL absente ou invalide : nom par défaut */ }

  out.push({
    json: {
      to: conf.to,
      cc: conf.cc,
      subject: conf.subject,
      fromName: FROM_NAME,
      body,
      fileUrl,
      fileName,
      campus: conf.campus,
      formId: fr.form_id,
      submittedAt: fr.submitted_at,
    },
  });
}

return out;
